  const arr = v => [+v.x.toFixed(3), +v.y.toFixed(3), +v.z.toFixed(3)];

  const hairline = H.hairline;

  function kit(fit, G) {
    const sp = (th, ph, off) => H.scalpPoint(fit, th * D2R, ph * D2R, off == null ? 0.6 : off);
    // a strand from a list of {p, n}
    const strand = (list, o) => H.newStrand(Object.assign({ pts: list.map(q => arr(q.p)), nrm: list.map(q => arr(q.n)) }, o || {}));
    // a path over her scalp between two (theta, phi) points, slerping directions
    const over = (a, b, k, offA, offB) => {
      const out = [];
      const da = fit.dir(a[0] * D2R, a[1] * D2R), db = fit.dir(b[0] * D2R, b[1] * D2R), q = new THREE.Quaternion().setFromUnitVectors(da, db), id = new THREE.Quaternion();
      for (let i = 0; i < k; i++) {
        const t = i / (k - 1), qq = id.clone().slerp(q, t), d = da.clone().applyQuaternion(qq), th = Math.acos(clamp(d.y, -1, 1)), ph = Math.atan2(d.x, d.z);
        out.push(H.scalpPoint(fit, th, ph, lerp(offA == null ? 0.6 : offA, offB == null ? 0.6 : offB, t)));
      }
      return out;
    };
    const gp = (u, v, g2) => H.guidePoint(fit, Object.assign({}, G, g2 || {}), u, v);
    return { sp, strand, over, gp };
  }

  // ---------------------------------------------------------------- parts
  const PARTS = {};

  PARTS.baseUp = { label: 'Base, swept back', icon: 'arrow_up', make(fit, G, o) { return PARTS.base.make(fit, G, Object.assign({}, o, { up: true })); } };
  PARTS.base = { label: 'Base', icon: 'sphere', make(fit, G, o) {
    // mirrored (for a split colour): only her left half, the mirror makes the right
    const half = !!(o && o.mirror), K = kit(fit, G), n = half ? 15 : 28, S = [];
    for (let i = 0; i < n; i++) {
      const ph = half ? lerp(7, 173, i / (n - 1)) : i / n * 360 + (i % 2) * 3, th1 = hairline(ph) + 3 + (i % 3 === 0 ? 3 : 0);
      const pts = K.over([half ? 9 : 0.5, ph], [th1, ph], 6, 0.3, 0.42); S.push(K.strand(o && o.up ? pts.reverse() : pts));
    }
    if (o && o.up) return [H.newGroup(Object.assign({ name: 'Base hair', kind: 'base', section: 'flat', width: 8.5, thickness: 0.12, profile: [1, 1, 1, 0.85, 0.35], rootInset: 0.15, smooth: 16, rootShade: 0.15, texScale: 1.6 }, o, { up: undefined, strands: S }))];
    return [H.newGroup(Object.assign({ name: 'Base hair', kind: 'base', section: 'flat', width: 8.5, thickness: 0.12, profile: [1, 1, 1, 0.8, 0], rootInset: 0, smooth: 16, layer: 0, rootShade: 0.35, texScale: 1.6 }, o, { strands: S }))];
  } };

  PARTS.bangs = { label: 'Bangs', icon: 'hair', make(fit, G, o) {
    const K = kit(fit, G), n = 8, S = [];
    for (let i = 0; i < n; i++) {
      const f = i / (n - 1) - 0.5, ph = f * 110, edge = Math.abs(f) * 2;
      S.push(K.strand([K.sp(12, ph * 0.35, 0.5), K.sp(38, ph * 0.8, 0.6), K.sp(60, ph * 0.95, 0.8), K.sp(lerp(81, 74, edge), ph * 0.92, 1.1)]));
    }
    return [H.newGroup(Object.assign({ name: 'Bangs', kind: 'bangs', width: 4.6, thickness: 0.32, section: 'arc', profile: [1, 1, 0.85, 0.55, 0] }, o, { strands: S }))];
  } };

  PARTS.sweptBangs = { label: 'Side swept', icon: 'wind', make(fit, G, o) {
    const K = kit(fit, G), n = 7, S = [];
    for (let i = 0; i < n; i++) {
      const f = i / (n - 1), ph = lerp(-55, 45, f);
      S.push(K.strand([K.sp(12, ph * 0.3 - 20, 0.5), K.sp(38, ph * 0.7 + 4, 0.6), K.sp(60, ph + 18, 0.8), K.sp(lerp(70, 84, f), ph + 40, 1.1)]));
    }
    return [H.newGroup(Object.assign({ name: 'Side swept bangs', kind: 'bangs', width: 5, thickness: 0.32, profile: [1, 1, 0.85, 0.5, 0], twist: 0.1 }, o, { strands: S }))];
  } };

  PARTS.curtain = { label: 'Curtain bangs', icon: 'doors', make(fit, G, o) {
    const K = kit(fit, G), n = 4, S = [];
    for (let i = 0; i < n; i++) { const f = i / (n - 1), ph = lerp(6, 38, f); S.push(K.strand([K.sp(12, ph * 0.5 + 2, 0.5), K.sp(38, ph + 6, 0.65), K.sp(62, ph + 24, 0.9), K.sp(lerp(82, 74, f), ph + 40, 1.1)])); }
    return [H.newGroup(Object.assign({ name: 'Curtain bangs', kind: 'bangs', mirror: true, width: 5.2, thickness: 0.32, profile: [1, 1, 0.9, 0.55, 0] }, o, { strands: S }))];
  } };

  PARTS.sidelocks = { label: 'Side locks', icon: 'arrow_double_vertical', make(fit, G, o) {
    const K = kit(fit, G), S = [];
    [[58, 0], [70, 1]].forEach(([ph, k]) => S.push(K.strand([K.sp(30, ph, 0.6), K.sp(62, ph + 8, 0.9), K.gp((ph + 14) / 360, 0.62, { offset: 1.2 }), K.gp((ph + 10) / 360, 0.8, { offset: 1.2, bottom: fit.chinY - 9 + k * 2, flare: 0.05 })])));
    return [H.newGroup(Object.assign({ name: 'Side locks', kind: 'locks', mirror: true, width: 3.6, thickness: 0.35, profile: [1, 1, 0.9, 0.6, 0] }, o, { strands: S }))];
  } };

  PARTS.long = { label: 'Long', icon: 'arrow_down_to_line', make(fit, G, o) {
    const K = kit(fit, G), n = 13, S = [], g2 = { bottom: (o && o.bottom) || fit.chinY - ((o && o.drop) || 26), flare: (o && o.flare) || 0.42, offset: 0.7 };
    for (let i = 0; i < n; i++) {
      const u = lerp(0.2, 0.8, i / (n - 1)), vs = [0.05, 0.22, 0.4, 0.55, 0.66, 0.78, 0.9, 1].map(v => v);
      S.push(K.strand(vs.map(v => K.gp(u, v, g2))));
    }
    return [H.newGroup(Object.assign({ name: 'Long hair', kind: 'long', width: 6.2, thickness: 0.3, section: 'crescent', profile: [1, 1, 0.95, 0.7, 0], smooth: 28 }, o, { strands: S }))];
  } };

  PARTS.bob = { label: 'Bob', icon: 'bell', make(fit, G, o) {
    const K = kit(fit, G), n = 12, S = [], g2 = { bottom: fit.chinY - 2, flare: 0.12, offset: 0.9 };
    for (let i = 0; i < n; i++) {
      const u = lerp(0.14, 0.86, i / (n - 1)), list = [0.05, 0.25, 0.45, 0.6, 0.8].map(v => K.gp(u, v, g2)), last = list[list.length - 1], prev = list[list.length - 2];
      const tip = { p: last.p.clone().addScaledVector(last.n, -1.6).add(V(0, 0.8, 0)), n: last.n.clone() };
      if (!(o && o.straight)) list.push(tip); S.push(K.strand(list));
    }
    return [H.newGroup(Object.assign({ name: 'Bob', kind: 'bob', width: 6.4, thickness: 0.32, section: 'crescent', profile: [1, 1, 1, 0.75, 0] }, o, { strands: S }))];
  } };

  PARTS.pixie = { label: 'Pixie', icon: 'leaf', make(fit, G, o) {
    const K = kit(fit, G), S = [], n = 46, ga = Math.PI * (3 - Math.sqrt(5));
    for (let i = 0; i < n; i++) {
      const y = 1 - (i + 0.5) / n * 1.15, th = Math.acos(clamp(y, -1, 1)) / D2R, ph = (i * ga / D2R) % 360;
      const hl = hairline(ph); if (th > hl - 6) continue;
      const th2 = Math.min(hl + 4, th + 40), ph2 = ph + (ph < 180 ? 8 : -8);
      if (th2 - th < 10) continue;
      S.push(K.strand([K.sp(th, ph, 0.45), K.sp(lerp(th, th2, 0.4), lerp(ph, ph2, 0.4), 0.6), K.sp(lerp(th, th2, 0.75), lerp(ph, ph2, 0.75), 0.8), K.sp(th2, ph2, 1.15)]));
    }
    return [H.newGroup(Object.assign({ name: 'Pixie', kind: 'pixie', section: 'flat', width: 3.6, thickness: 0.2, profile: [1, 0.95, 0.75, 0.42, 0], lift: 0.15 }, o, { strands: S }))];
  } };

  PARTS.spikes = { label: 'Spikes', icon: 'spikes', make(fit, G, o) {
    const K = kit(fit, G), S = [], n = 14;
    for (let i = 0; i < n; i++) {
      const ph = 120 + i / (n - 1) * 120 + (i % 2) * 8, th = 30 + (i % 3) * 14, a = K.sp(th, ph, 0.4), back = V(0, 0.35, 0).add(a.n.clone().multiplyScalar(0.9)).normalize();
      const p1 = a.p.clone().addScaledVector(back, 3.5), p2 = a.p.clone().addScaledVector(back, 7).add(V(0, -1, -1));
      S.push(K.strand([a, { p: p1, n: a.n }, { p: p2, n: a.n }], { root: true }));
    }
    return [H.newGroup(Object.assign({ name: 'Spikes', kind: 'spikes', width: 4.4, thickness: 0.6, section: 'diamond', profile: [1, 0.85, 0.55, 0.25, 0] }, o, { strands: S }))];
  } };

  PARTS.ahoge = { label: 'Ahoge', icon: 'magic_wand', make(fit, G, o) {
    const K = kit(fit, G), r = K.sp(14, 0, 0.3), up = V(0, 1, 0), fw = V(0, 0, 1), side = V(1, 0, 0);
    const at = (u, f) => ({ p: r.p.clone().addScaledVector(up, u).addScaledVector(fw, f), n: side.clone() });
    const S = [K.strand([at(0, 0), at(3.6, 0.6), at(6.6, 3.4), at(6.4, 7), at(3.6, 8.6)]), K.strand([at(0, -0.6), at(3, -1.8), at(4.6, -4.4), at(3.6, -7.2)], { w: 0.75 })];
    return [H.newGroup(Object.assign({ name: 'Ahoge', kind: 'ahoge', width: 2.6, thickness: 0.5, section: 'crescent', profile: [1, 1, 0.9, 0.55, 0], rootInset: 0.6 }, o, { strands: S }))];
  } };

  // gather strands from her hairline to a tie point (ponytails, buns, braids)
  function gather(fit, K, tie, phFrom, phTo, n, o) {
    const S = [], tieDir = fit.dir(tie[0] * D2R, tie[1] * D2R);
    for (let i = 0; i < n; i++) {
      const ph = lerp(phFrom, phTo, n === 1 ? 0.5 : i / (n - 1)), th = hairline(ph) - 4;
      const pts = K.over([th, ph], tie, 7, 0.45, 0.9);
      S.push(K.strand(pts));
    }
    return H.newGroup(Object.assign({ name: 'Gathered', kind: 'gather', width: 7.5, thickness: 0.16, section: 'flat', profile: [1, 1, 0.85, 0.55, 0.15], rootInset: 0.25, smooth: 24, layer: 0.1 }, o, { strands: S }));
  }
  function tiePoint(fit, th, ph, out) { const s = H.scalpPoint(fit, th * D2R, ph * D2R, out); return s; }

  function tail(fit, K, T, out, len, n, o, sideways) {
    // strands hang from the gathering point: out from her head, then down, fanned around the tail's axis
    const S = [], down = V(0, -1, 0), o1 = out.clone();
    for (let i = 0; i < n; i++) {
      const a = i / n * TAU, rr = i === 0 ? 0 : 1;
      const pts = [];
      for (let k = 0; k <= 6; k++) {
        const t = k / 6, axis = T.clone().addScaledVector(o1, 3.2 * Math.sin(Math.min(1, t * 2) * Math.PI / 2) + (sideways ? t * 2.5 : 0)).addScaledVector(down, len * Math.pow(t, 1.25));
        const tan = o1.clone().multiplyScalar(1 - t).addScaledVector(down, t + 0.2).normalize();
        const b1 = new THREE.Vector3().crossVectors(tan, V(0, 0, 1)); if (b1.lengthSq() < 0.1) b1.crossVectors(tan, V(1, 0, 0)); b1.normalize();
        const b2 = new THREE.Vector3().crossVectors(tan, b1).normalize(), rad = (0.9 + 1.9 * Math.sin(Math.PI * Math.min(1, t * 1.2)) * (1 - 0.4 * t)) * rr;
        const dir = b1.clone().multiplyScalar(Math.cos(a)).addScaledVector(b2, Math.sin(a));
        pts.push({ p: axis.clone().addScaledVector(dir, rad), n: i === 0 ? out.clone() : dir.clone() });
      }
      S.push(K.strand(pts, { root: false, w: i === 0 ? 1.15 : 1 }));
    }
    return H.newGroup(Object.assign({ name: 'Tail', kind: 'tail', width: 5.2, thickness: 0.34, section: 'crescent', profile: [0.55, 1, 0.95, 0.6, 0], rootInset: 0, smooth: 28 }, o, { strands: S }));
  }

  PARTS.ponytail = { label: 'Ponytail', icon: 'arrow_turn_down_right', make(fit, G, o) {
    const K = kit(fit, G), th = (o && o.tieTheta) || 98, T = tiePoint(fit, th, 180, 1.4);
    const base = gather(fit, K, [th, 180], -150, 150, 15, { name: 'Ponytail base' });
    const tl = tail(fit, K, T.p.clone().addScaledVector(T.n, 0.6), T.n, (o && o.len) || 24, 9, { name: 'Ponytail' });
    return [base, tl];
  } };
  PARTS.highPony = { label: 'High ponytail', icon: 'arrow_turn_up_right', make(fit, G, o) { return PARTS.ponytail.make(fit, G, Object.assign({ tieTheta: 52, len: 30 }, o)); } };

  PARTS.pigtails = { label: 'Pigtails', icon: 'arrow_split', make(fit, G, o) {
    const K = kit(fit, G), th = (o && o.tieTheta) || 70, ph = 112, T = tiePoint(fit, th, ph, 1.3);
    const base = gather(fit, K, [th, ph], 4, 176, 9, { name: 'Pigtail base', mirror: true });
    const out = T.n.clone().add(V(0, 0.15, -0.15)).normalize();
    const tl = tail(fit, K, T.p.clone().addScaledVector(out, 0.6), out, (o && o.len) || 22, 8, { name: 'Pigtails', mirror: true }, true);
    return [base, tl];
  } };
  PARTS.twintails = { label: 'Twin tails', icon: 'arrow_split', make(fit, G, o) { return PARTS.pigtails.make(fit, G, Object.assign({ tieTheta: 48, len: 34 }, o)); } };

  function bun(fit, K, th, ph, r, o) {
    const T = tiePoint(fit, th, ph, 0.6), c = T.p.clone().addScaledVector(T.n, r * 0.7), S = [], n = 9;
    for (let i = 0; i < n; i++) {
      // loops around the core, each turned a little further around the bun's axis
      const ax = T.n.clone(), a = i / n * Math.PI, side = new THREE.Vector3().crossVectors(ax, V(0, 1, 0)); if (side.lengthSq() < 0.1) side.set(1, 0, 0); side.normalize();
      const up = new THREE.Vector3().crossVectors(side, ax).normalize(), plane = side.clone().multiplyScalar(Math.cos(a)).addScaledVector(up, Math.sin(a));
      const e1 = plane.clone(), e2 = new THREE.Vector3().crossVectors(plane, ax).normalize().lerp(ax, 0.35).normalize(), pts = [];
      for (let k = 0; k <= 7; k++) { const ang = -1.4 + k / 7 * 4.6, d = e1.clone().multiplyScalar(Math.cos(ang)).addScaledVector(e2, Math.sin(ang)).normalize(); pts.push({ p: c.clone().addScaledVector(d, r * 1.02), n: d }); }
      S.push(K.strand(pts, { root: false }));
    }
    return H.newGroup(Object.assign({ name: 'Bun', kind: 'bun', width: 4.6, thickness: 0.3, section: 'arc', profile: [0.4, 1, 1, 0.8, 0], rootInset: 0, smooth: 26, core: { pos: arr(c), r: r * 0.95, squash: 0.92 } }, o, { strands: S }));
  }
  PARTS.bun = { label: 'Bun', icon: 'circle', make(fit, G, o) {
    const K = kit(fit, G), th = (o && o.tieTheta) || 58, base = gather(fit, K, [th, 180], -150, 150, 15, { name: 'Bun base' });
    return [base, bun(fit, K, th, 180, 4.6, { name: 'Bun' })];
  } };
  PARTS.topBun = { label: 'Top bun', icon: 'circle_half_filled', make(fit, G, o) { return PARTS.bun.make(fit, G, Object.assign({ tieTheta: 22 }, o)); } };
  PARTS.spaceBuns = { label: 'Space buns', icon: 'planet', make(fit, G, o) {
    const K = kit(fit, G), base = gather(fit, K, [36, 62], 4, 176, 9, { name: 'Space bun base', mirror: true });
    return [base, bun(fit, K, 36, 62, 3.9, { name: 'Space buns', mirror: true })];
  } };

  PARTS.braid = { label: 'Braid', icon: 'knot', make(fit, G, o) {
    const K = kit(fit, G), th = 104, T = tiePoint(fit, th, 180, 1.2), base = gather(fit, K, [th, 180], -150, 150, 15, { name: 'Braid base' });
    const S = [], len = 30, down = V(0, -1, 0), back = T.n.clone().setY(0).normalize(), side = new THREE.Vector3().crossVectors(down, back).normalize(), steps = 26, turns = 4.2;
    const axis = t => T.p.clone().addScaledVector(back, 1.5 + 2 * Math.sin(Math.min(1, t * 3) * Math.PI / 2)).addScaledVector(down, len * t);
    for (let i = 0; i < 3; i++) {
      const pts = [];
      for (let k = 0; k <= steps; k++) {
        const t = k / steps, a = TAU * turns * t + i * TAU / 3, w = 1.25 * (1 - 0.35 * t);
        const off = side.clone().multiplyScalar(Math.sin(a) * w).addScaledVector(back, Math.sin(2 * a) * w * 0.45);
        pts.push({ p: axis(t).add(off), n: back.clone().addScaledVector(side, Math.sin(a) * 0.6).normalize() });
      }
      S.push(K.strand(pts, { root: false }));
    }
    const br = H.newGroup({ name: 'Braid', kind: 'braid', width: 2.9, thickness: 0.85, section: 'round', profile: [1, 1, 1, 0.92, 0.8], rootInset: 0, smooth: 70, strands: S });
    const end = axis(1), tuft = [];
    for (let i = 0; i < 6; i++) { const a = i / 6 * TAU, d = side.clone().multiplyScalar(Math.cos(a)).addScaledVector(back, Math.sin(a)); tuft.push(K.strand([{ p: end.clone().addScaledVector(d, 0.3), n: d }, { p: end.clone().addScaledVector(d, 1.3).add(V(0, -2.5, 0)), n: d }, { p: end.clone().addScaledVector(d, 1.8).add(V(0, -5.5, 0)), n: d }], { root: false })); }
    const tf = H.newGroup({ name: 'Braid end', kind: 'tail', width: 2.6, thickness: 0.4, profile: [0.6, 1, 0.9, 0.5, 0], rootInset: 0, strands: tuft });
    return [base, br, tf];
  } };


  // ---------------------------------------------------------------- more parts (added while recreating catalog styles)
  PARTS.bluntBangs = { label: 'Blunt bangs', icon: 'minus_in_square', make(fit, G, o) {
    const K = kit(fit, G), n = 11, S = [];
    for (let i = 0; i < n; i++) { const f = i / (n - 1) - 0.5, ph = f * 118, e = Math.abs(f) * 2; S.push(K.strand([K.sp(10, ph * 0.3, 0.5), K.sp(36, ph * 0.75, 0.65), K.sp(58, ph * 0.95, 0.85), K.sp(lerp(77, 73, e * e), ph, 1.15)])); }
    return [H.newGroup(Object.assign({ name: 'Blunt bangs', kind: 'bangs', width: 4.4, thickness: 0.32, section: 'crescent', profile: [1, 1, 1, 1, 0.94], smooth: 22 }, o, { strands: S }))];
  } };

  // long hair from a middle part: strands start on the parting and fall to each side (mirrored)
  PARTS.partedLong = { label: 'Middle part', icon: 'arrow_split', make(fit, G, o) {
    const K = kit(fit, G), n = 7, S = [], bottom = (o && o.bottom) || fit.chinY - ((o && o.drop) || 24), g2 = { bottom, flare: (o && o.flare) || 0.38, offset: 1.0 };
    for (let i = 0; i < n; i++) {
      const k = i / (n - 1), thr = lerp(8, 52, k), phr = 7, phw = lerp(28, 92, k);
      const pts = K.over([thr, phr], [lerp(42, 70, k), lerp(14, 70, k)], 3, 0.55, 0.8);
      for (const v of [0.6, 0.72, 0.86, 1]) pts.push(K.gp(phw / 360, v, g2));
      S.push(K.strand(pts));
    }
    return [H.newGroup(Object.assign({ name: 'Middle part', kind: 'long', mirror: true, width: 5.8, thickness: 0.22, section: 'arc', profile: [0.3, 0.95, 1, 0.8, 0.1], smooth: 30, layer: 0.25, rootInset: 0.1 }, o, { strands: S }))];
  } };

  // face-framing curly tendrils
  PARTS.wisps = { label: 'Wisps', icon: 'sine_wave', make(fit, G, o) {
    const K = kit(fit, G), S = [];
    [[60, 52, 1], [74, 62, 0.8]].forEach(([th, ph, w]) => { const a = K.sp(th, ph, 0.6), b = K.gp((ph + 8) / 360, 0.6, { offset: 1.4 }), c = K.gp((ph + 6) / 360, 0.85, { offset: 1.6, bottom: fit.chinY - 8, flare: 0.1 }); S.push(K.strand([a, b, c], { w })); });
    return [H.newGroup(Object.assign({ name: 'Wisps', kind: 'locks', mirror: true, width: 1.5, thickness: 0.6, section: 'round', profile: [1, 1, 0.9, 0.7, 0.2], curl: 0.75, curlFreq: 3.2, rootInset: 0.2 }, o, { strands: S }))];
  } };

  // the top half pulled back to a twist at the back of her head
  PARTS.halfUp = { label: 'Half up', icon: 'arrow_turn_up_right', make(fit, G, o) {
    const K = kit(fit, G), th = 66, T = tiePoint(fit, th, 180, 1.2);
    const top = gather(fit, K, [th, 180], 0, 105, 7, { name: 'Half up', mirror: true, width: 6.5, thickness: 0.2, section: 'arc', layer: 0.55, profile: [1, 1, 0.9, 0.75, 0.3] });
    const S = [], down = V(0, -1, 0), out = T.n.clone().setY(0).normalize();
    for (let i = 0; i < 3; i++) { const a = i / 3 * TAU, pts = []; for (let k = 0; k <= 8; k++) { const t = k / 8, ang = a + t * TAU * 1.6, r = 0.9 * (1 - 0.5 * t), side = new THREE.Vector3(1, 0, 0); pts.push({ p: T.p.clone().addScaledVector(out, 1.2 + Math.cos(ang) * r).addScaledVector(side, Math.sin(ang) * r).addScaledVector(down, 9.5 * t), n: out.clone() }); } S.push(K.strand(pts, { root: false })); }
    const tw = H.newGroup({ name: 'Twist', kind: 'tail', width: 3.4, thickness: 0.7, section: 'crescent', profile: [1, 1, 0.95, 0.7, 0], rootInset: 0, smooth: 34, strands: S });
    return [top, tw];
  } };

