    d.mic = d.kind === 'over' && r.chance(theme === 'night' ? 0.4 : 0.14); d.glow = d.kind === 'over' && r.chance(theme === 'night' || theme === 'halloween' ? 0.35 : kimi ? 0.15 : 0.12);
