    if (top !== 'none') t.push(TOPPER_LABEL[top]); if (d.kind === 'over') t.push(CUP_LABEL[d.cup] + ' cups'); if (d.kind === 'buds') t.push(BUD_LABEL[d.bud] + ' buds');
