  const sUV = (r, fx, fy) => { const [x0, y0, w, h] = SREG[r]; return [(x0 + 2 + clamp(fx, 0, 1) * (w - 4)) / TW, 1 - (y0 + 2 + clamp(fy, 0, 1) * (h - 4)) / TW]; };
